=========== utils/safeHref.ts ===========
/**
 * Allow-list guard for hrefs that originate outside the codebase.
 *
 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
 * execute; a protocol-relative `//host` silently leaves the site. The `(?!\/)` lookahead is
 * what rejects the last case — it was a real bypass, closed in e9c2180.
 *
 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?!\/))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(href) : false);

=========== utils/safeHref.test.ts ===========
import { describe, test, expect } from 'vitest';
import { isSafeHref } from './safeHref';

/**
 * The guard is a security boundary — every consumer renders an anchor on its say-so — so the
 * rejection cases matter more than the acceptances. `//example.com` is the one that regressed
 * before (e9c2180) and is the reason the pattern carries a negative lookahead.
 */
describe('isSafeHref', () => {
  test.each([
    ['/womens', true],
    ['https://zimmermann.com', true],
    ['http://zimmermann.com', true],
    ['tel:+61280808080', true],
    ['mailto:care@zimmermann.com', true],
    ['#top', true],
  ])('allows %s', (href, expected) => {
    expect(isSafeHref(href)).toBe(expected);
  });

  test.each([
    ['javascript:void(0)', false],
    ['JavaScript:alert(1)', false],
    ['data:text/html,<script>alert(1)</script>', false],
    ['//example.com', false],
    ['vbscript:msgbox(1)', false],
    ['', false],
  ])('rejects %s', (href, expected) => {
    expect(isSafeHref(href)).toBe(expected);
  });

  test('treats undefined as unsafe rather than throwing', () => {
    expect(isSafeHref(undefined)).toBe(false);
  });
});

=========== hooks/useZimmTextInputState.ts ===========
import { useRef, useState } from 'react';
import type React from 'react';

type UseZimmTextInputStateParams = {
  onChange?: (value: string) => void;
  /** Controlled value. When provided the caller owns the value and internal state is unused. */
  value?: string;
  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
  defaultValue?: string;
};

type UseZimmTextInputStateReturn = {
  value: string;
  focused: boolean;
  /** Label is floated when the field is focused or has a value. */
  floated: boolean;
  inputRef: React.RefObject<HTMLInputElement>;
  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handleClear: () => void;
  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
};

/**
 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
 * focus, and the derived floated-label flag. Visual tokens are NOT derived here — the border
 * and label colour cascades live in `theme/components/zimmTextInput.ts`, which receives
 * `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that recipe, so it
 * costs no React state.
 *
 * Supports both modes, following the React convention: pass `value` to control it from a
 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
 * seeded from `defaultValue`. `onChange` fires in both modes.
 * @returns value, focus and floated flags, the input ref, and the event handlers
 */
export const useZimmTextInputState = ({
  onChange,
  value: controlledValue,
  defaultValue,
}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
  // `defaultValue`. Reading `value` through this indirection keeps `floated` correct in
  // both modes.
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
  const value = isControlled ? controlledValue : internalValue;
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const floated = focused || value.length > 0;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isControlled) setInternalValue(e.target.value);
    onChange?.(e.target.value);
  };

  const handleClear = () => {
    if (!isControlled) setInternalValue('');
    onChange?.('');
    inputRef.current?.focus();
  };

  return { value, focused, floated, inputRef, handleChange, handleClear, setFocused };
};

=========== hooks/useZimmTextInputState.test.ts ===========
import { afterEach, describe, test, expect, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useZimmTextInputState } from './useZimmTextInputState';

/**
 * The value-ownership switch is the thing in this hook that can break without surfacing as a
 * type or build error: a controlled input that silently keeps its own state looks correct
 * until a parent form tries to reset it.
 *
 * The derived-colour cascade used to live here too. It now lives in
 * `theme/components/zimmTextInput.ts` and is covered by that file's own test.
 */

const change = (v: string) => ({ target: { value: v } } as unknown as React.ChangeEvent<HTMLInputElement>);

afterEach(() => {
  vi.clearAllMocks();
});

describe('useZimmTextInputState — value ownership', () => {
  test('is uncontrolled by default and starts empty', () => {
    const { result } = renderHook(() => useZimmTextInputState({}));
    expect(result.current.value).toBe('');
  });

  test('seeds the uncontrolled value from defaultValue', () => {
    const { result } = renderHook(() => useZimmTextInputState({ defaultValue: 'seed' }));
    expect(result.current.value).toBe('seed');
  });

  test('uncontrolled: a change updates the value and notifies the caller', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() => useZimmTextInputState({ onChange }));
    act(() => {
      result.current.handleChange(change('hello'));
    });
    expect(result.current.value).toBe('hello');
    expect(onChange).toHaveBeenCalledWith('hello');
  });

  test('uncontrolled: clearing resets the value and notifies with an empty string', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() => useZimmTextInputState({ onChange, defaultValue: 'x' }));
    act(() => {
      result.current.handleClear();
    });
    expect(result.current.value).toBe('');
    expect(onChange).toHaveBeenCalledWith('');
  });

  test('controlled: the value comes from the prop, not internal state', () => {
    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned' }));
    expect(result.current.value).toBe('owned');
  });

  test('controlled: a change notifies the caller but does not move the value itself', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned', onChange }));
    act(() => {
      result.current.handleChange(change('typed'));
    });
    expect(result.current.value).toBe('owned');
    expect(onChange).toHaveBeenCalledWith('typed');
  });

  test('controlled: defaultValue is ignored', () => {
    const { result } = renderHook(() => useZimmTextInputState({ value: 'owned', defaultValue: 'seed' }));
    expect(result.current.value).toBe('owned');
  });

  test('controlled: a new prop value is reflected on re-render', () => {
    const { result, rerender } = renderHook(({ value }: { value: string }) => useZimmTextInputState({ value }), {
      initialProps: { value: 'first' },
    });
    rerender({ value: 'second' });
    expect(result.current.value).toBe('second');
  });
});

describe('useZimmTextInputState — floated label', () => {
  test('floats when the field has a value', () => {
    const { result } = renderHook(() => useZimmTextInputState({ value: 'v' }));
    expect(result.current.floated).toBe(true);
  });

  test('floats while focused even when empty', () => {
    const { result } = renderHook(() => useZimmTextInputState({}));
    expect(result.current.floated).toBe(false);
    act(() => {
      result.current.setFocused(true);
    });
    expect(result.current.floated).toBe(true);
  });
});

