// NOT connected to any Contentful sync script.
// This file lives inside the component folder deliberately — it is a
// design placeholder for the footer content type schema, prepared ahead
// of the Contentful story. It will be moved to scripts/contentful/content-types/
// and wired into the sync script only when that story is scheduled.

// Three content types compose the footer:
//   footerNavLink  — atom    — a single labelled hyperlink
//   footerNavGroup — molecule — a labelled column of footerNavLink references
//   footerConfig   — organism — the root footer entry (one per locale)

type ContentfulFieldDef = {
  id: string;
  name: string;
  type: string;
  required: boolean;
  items?: {
    type: string;
    linkType: string;
    validations: Array<{ linkContentType: string[] }>;
  };
};

type ContentfulContentTypeDef = {
  id: string;
  name: string;
  displayField: string;
  description: string;
  fields: ContentfulFieldDef[];
};

const footerNavLink: ContentfulContentTypeDef = {
  id: 'footerNavLink',
  name: 'Footer Nav Link',
  displayField: 'label',
  description: 'A single navigation link rendered inside a footer column.',
  fields: [
    { id: 'label', name: 'Label', type: 'Symbol', required: true },
    { id: 'href', name: 'URL', type: 'Symbol', required: true },
  ],
};

const footerNavGroup: ContentfulContentTypeDef = {
  id: 'footerNavGroup',
  name: 'Footer Nav Group',
  displayField: 'heading',
  description: 'A labelled column of footer nav links (About, Contact, Help, etc.).',
  fields: [
    { id: 'heading', name: 'Heading', type: 'Symbol', required: true },
    // Which column carries the contact icons. A flag, not a heading match — heading is
    // localised, so matching its text breaks per storefront.
    { id: 'showContactChannels', name: 'Show Contact Channels', type: 'Boolean', required: false },
    {
      id: 'links',
      name: 'Links',
      type: 'Array',
      required: true,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['footerNavLink'] }] },
    },
  ],
};

const footerConfig: ContentfulContentTypeDef = {
  id: 'footerConfig',
  name: 'Footer Config',
  displayField: 'internalTitle',
  description: 'Root footer entry — one per locale.',
  fields: [
    { id: 'internalTitle', name: 'Internal Title', type: 'Symbol', required: true },
    { id: 'subscribeHeading', name: 'Subscribe Heading', type: 'Symbol', required: false },
    { id: 'subscribeBody', name: 'Subscribe Body', type: 'Symbol', required: false },
    {
      id: 'navGroups',
      name: 'Nav Groups',
      type: 'Array',
      required: true,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['footerNavGroup'] }] },
    },
    {
      id: 'legalLinks',
      name: 'Legal Links',
      type: 'Array',
      required: false,
      items: { type: 'Link', linkType: 'Entry', validations: [{ linkContentType: ['footerNavLink'] }] },
    },
    { id: 'copyrightOwner', name: 'Copyright Owner', type: 'Symbol', required: false },
    // Contact channels rendered by ContactIconRow. Optional: a storefront without a
    // channel renders that icon non-interactive rather than hiding the row. Values are
    // passed through isSafeHref before reaching an anchor, so an editor cannot introduce
    // a javascript:/data: URL from the CMS.
    { id: 'phoneHref', name: 'Phone Href', type: 'Symbol', required: false },
    { id: 'whatsAppHref', name: 'WhatsApp Href', type: 'Symbol', required: false },
    { id: 'emailHref', name: 'Email Href', type: 'Symbol', required: false },
  ],
};

export const footerContentTypes: ContentfulContentTypeDef[] = [footerNavLink, footerNavGroup, footerConfig];

