  name: 'Inverse + Error',
  args: {
    label: 'Email address',
    inverse: true,
    errorText: 'Please enter a valid email address',
  },
  decorators: [
    (Story) => (
      <Box bg="background.05" p="xl">
        <Story />
      </Box>
    ),
  ],
};

