const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';

const SubscribeSection = ({ heading, body, initialSubscribed = false, privacyPolicyHref }: SubscribeSectionProps) => {
  // Map the Storybook-only `initialSubscribed` flag to the success state.
  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted.
  // The footer input unmounts once submitState leaves 'idle', so the email must be
  // captured here at step 1 or it is unrecoverable at step 2.
  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
  const [modalOpen, setModalOpen] = useState(false);
  const styles = useMultiStyleConfig('ZimmFooter', {});

  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    setModalOpen(true);
  };

  const handleModalSubmit = (firstName: string, lastName: string) => {
    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
    // 'unavailable' is shown until the integration is live; never show false success.
    setModalOpen(false);
    setSubmitState('unavailable');
    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there
    // is no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it
    // just moves to after a confirmed response. React memory only, never storage, never logged.
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  return (
    <div>
      <chakra.p __css={styles.subscribeHeading}>{heading}</chakra.p>
